const n84=node({type:"n8n-nodes-base.code",version:2,config:{"name":"Assert business policy fixtures","parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"const intents=['demo','pricing','purchase','support','partnership','job','student','spam','unknown'];\nfunction normalize(input){\n if(!input||typeof input!=='object'||Array.isArray(input))throw Error('INVALID_PAYLOAD');\n const text=(key,max=300)=>typeof input[key]==='string'?input[key].normalize('NFKC').trim().slice(0,max):'';\n const email=text('email',254).toLowerCase()||null;\n const phone=text('phone',40).replace(/[\\s().-]/g,'')||null;\n const errors=[];\n if(!email&&!phone)errors.push('MISSING_CONTACT');\n if(email&&!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email))errors.push('INVALID_EMAIL');\n if(phone&&!/^\\+[1-9]\\d{7,14}$/.test(phone))errors.push('INVALID_PHONE');\n if(!text('source',40)||!text('source_event_id',160))errors.push('MISSING_EVENT_ID');\n return {lead:{source:text('source',40),source_event_id:text('source_event_id',160),name:text('name'),email,phone,company_name:text('company_name'),company_domain:text('company_domain').toLowerCase().replace(/^https?:\\/\\//,'').split('/')[0]||email?.split('@')[1]||null,job_title:text('job_title'),country:text('country',2).toUpperCase(),message:text('message',8000),consent:input.consent===true},errors};\n}\nfunction score(lead,signals,config){\n const b={fit:(lead.company_name?20:0)+(signals.authority_signal==='decision_maker'?20:signals.authority_signal==='influencer'?10:0),intent:({purchase:30,demo:30,pricing:25})[signals.intent]||0,urgency:({immediate:15,quarter:8,later:3,unknown:0})[signals.urgency]||0,engagement:lead.consent?15:0};\n for(const key of Object.keys(b))b[key]=Math.round(b[key]*config.weights[key]/({fit:40,intent:30,urgency:15,engagement:15})[key]);\n const value=Math.min(100,Object.values(b).reduce((a,v)=>a+v,0));\n let route=value>=config.thresholds.HOT?'HOT':value>=config.thresholds.WARM?'WARM':value>=config.thresholds.NURTURE?'NURTURE':'LOW';\n if(['support','job','student','partnership','spam'].includes(signals.intent))route='REJECT';\n else if(signals.confidence<config.minimum_confidence||signals.intent==='unknown'||signals.risk_flags.length)route='MANUAL_REVIEW';\n return {score:value,route,breakdown:b,config_version:config.version};\n}\nconst transitions={NEW:['QUALIFIED','NURTURE','MANUAL_REVIEW','DISQUALIFIED','SPAM'],QUALIFIED:['CONTACTED','MANUAL_REVIEW','DISQUALIFIED'],CONTACTED:['RESPONDED','MANUAL_REVIEW','DISQUALIFIED'],RESPONDED:['MEETING_PROPOSED','MANUAL_REVIEW','DISQUALIFIED'],MEETING_PROPOSED:['MEETING_BOOKED','MANUAL_REVIEW','DISQUALIFIED'],MEETING_BOOKED:['OPPORTUNITY','MANUAL_REVIEW'],OPPORTUNITY:['WON','LOST','MANUAL_REVIEW'],NURTURE:['QUALIFIED','MANUAL_REVIEW','DISQUALIFIED'],MANUAL_REVIEW:['QUALIFIED','NURTURE','DISQUALIFIED','SPAM'],DISQUALIFIED:[],SPAM:[],WON:[],LOST:[]};\nfunction transitionAllowed(from,to){return from===to||!!transitions[from]?.includes(to);}\nfunction retryPlan({status=0,attempt=0,unsafe=false,ambiguous=false}){const transient=status===429||status===408||status>=500||status===0;if(unsafe&&ambiguous)return {class:'uncertain',retry:false,delay_ms:null};return {class:transient?'transient':'permanent',retry:transient&&attempt<3,delay_ms:transient&&attempt<3?[5000,30000,120000][attempt]:null};}\nfunction outreachPolicy(lead,draft,knowledge,route){\n const reasons=[];\n if(!lead.consent||lead.opted_out)reasons.push('NO_CONSENT');\n if(!lead.email)reasons.push('NO_EMAIL');\n if(!knowledge.approved)reasons.push('KNOWLEDGE_UNAPPROVED');\n if(!draft||typeof draft.subject!=='string'||typeof draft.body!=='string'||!Array.isArray(draft.claim_ids))return {allowed:false,approval_required:true,reasons:['INVALID_DRAFT']};\n const approved=knowledge.claims.filter(c=>draft.claim_ids.includes(c.id));\n if(!approved.length||approved.length!==draft.claim_ids.length)reasons.push('UNAPPROVED_CLAIM');\n const allowedBody=approved.map(c=>c.text).join(' ')+' '+knowledge.cta;\n if(draft.body!==allowedBody||draft.cta!==knowledge.cta||draft.subject!==`A discovery conversation about ${knowledge.product}`)reasons.push('UNSUPPORTED_CONTENT');\n const urls=draft.body.match(/https?:\\/\\/[^\\s]+/g)||[];if(urls.some(u=>!knowledge.allowed_urls.includes(u)))reasons.push('UNAPPROVED_URL');\n if(/[\\r\\n]/.test(draft.subject)||/\\b\\d{3}-\\d{2}-\\d{4}\\b|Bearer\\s+\\S+|sk-[a-zA-Z0-9]{12}/.test(draft.body))reasons.push('SENSITIVE_CONTENT');\n return {allowed:reasons.length===0,approval_required:route==='HOT'||route==='MANUAL_REVIEW',reasons};\n}\nfunction toolPolicy(name){if(['read_lead','read_company','read_deal','read_messages','read_product','read_calendar'].includes(name))return 'read';if(['crm_note','crm_task'].includes(name))return 'controlled';if(['external_send','deal_stage','discount','cancellation'].includes(name))return 'protected';return 'denied';}\nfunction followupEligible(lead,hasReply){return lead.status==='CONTACTED'&&lead.consent&&!lead.opted_out&&!hasReply&&lead.follow_up_count<3;}\nfunction redact(text){return String(text).replace(/[\\w.+-]+@[\\w.-]+\\.[a-zA-Z]{2,}/g,'[email]').replace(/\\+?\\d[\\d\\s().-]{7,}\\d/g,'[number]').replace(/(?:Bearer\\s+|sk-)[A-Za-z0-9_.-]+/g,'[secret]');}\n\nfunction matchesSchema(value,schema){\n if(schema.type==='object'){\n  if(value===null||typeof value!=='object'||Array.isArray(value))return false;\n  if((schema.required||[]).some(k=>!Object.hasOwn(value,k)))return false;\n  if(schema.additionalProperties===false&&Object.keys(value).some(k=>!Object.hasOwn(schema.properties,k)))return false;\n  return Object.entries(schema.properties||{}).every(([k,s])=>!Object.hasOwn(value,k)||matchesSchema(value[k],s));\n }\n if(schema.type==='array')return Array.isArray(value)&&(schema.maxItems===undefined||value.length<=schema.maxItems)&&value.every(v=>matchesSchema(v,schema.items));\n if(schema.type==='number')return typeof value==='number'&&Number.isFinite(value)&&(schema.minimum===undefined||value>=schema.minimum)&&(schema.maximum===undefined||value<=schema.maximum);\n if(schema.type==='string')return typeof value==='string'&&(!schema.enum||schema.enum.includes(value))&&(schema.maxLength===undefined||value.length<=schema.maxLength);\n if(schema.type==='boolean')return typeof value==='boolean';\n return false;\n}\nconst sample={\"source\":\"web\",\"source_event_id\":\"demo-hot-001\",\"name\":\"Synthetic CTO\",\"email\":\"cto@example.com\",\"company_name\":\"Example Labs\",\"company_domain\":\"example.com\",\"job_title\":\"CTO\",\"country\":\"EG\",\"message\":\"We need a demo of lead routing. I own the buying decision, have approved budget, and need to start this month.\",\"consent\":true},ctx={\"event_id\":\"11111111-1111-4111-8111-111111111111\",\"lead_id\":\"11111111-1111-4111-8111-111111111111\",\"correlation_id\":\"11111111-1111-4111-8111-111111111111\"},signals={\"intent\":\"demo\",\"needs\":[],\"pain_points\":[],\"buyer_role\":\"CTO\",\"urgency\":\"immediate\",\"budget_signal\":\"approved\",\"authority_signal\":\"decision_maker\",\"purchase_intent\":\"high\",\"timeline\":\"this month\",\"sentiment\":\"neutral\",\"risk_flags\":[],\"recommended_next_action\":\"discovery\",\"confidence\":0.95,\"evidence\":[\"Requests a demo\"]},draft={\"subject\":\"A discovery conversation about RevFlow AI\",\"body\":\"RevFlow AI helps teams organize inbound leads and route sales follow-up. Would a short discovery conversation be useful?\",\"cta\":\"Would a short discovery conversation be useful?\",\"claim_ids\":[\"lead-routing\"]},knowledge={\"version\":\"sales-v1\",\"approved\":true,\"product\":\"RevFlow AI\",\"claims\":[{\"id\":\"lead-routing\",\"text\":\"RevFlow AI helps teams organize inbound leads and route sales follow-up.\"},{\"id\":\"human-review\",\"text\":\"Sensitive outreach is reviewed by a person before sending.\"}],\"allowed_urls\":[\"https://example.com/revflow\"],\"cta\":\"Would a short discovery conversation be useful?\",\"pricing\":null,\"disclaimer\":\"Synthetic portfolio knowledge; replace and approve before live outreach.\"},scoring={\"version\":\"score-v1\",\"weights\":{\"fit\":40,\"intent\":30,\"urgency\":15,\"engagement\":15},\"thresholds\":{\"HOT\":80,\"WARM\":60,\"NURTURE\":40},\"minimum_confidence\":0.8},qualificationSchema={\"type\":\"object\",\"additionalProperties\":false,\"properties\":{\"intent\":{\"type\":\"string\",\"enum\":[\"demo\",\"pricing\",\"purchase\",\"support\",\"partnership\",\"job\",\"student\",\"spam\",\"unknown\"]},\"needs\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"maxItems\":12},\"pain_points\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"maxItems\":12},\"buyer_role\":{\"type\":\"string\"},\"urgency\":{\"type\":\"string\",\"enum\":[\"immediate\",\"quarter\",\"later\",\"unknown\"]},\"budget_signal\":{\"type\":\"string\",\"enum\":[\"approved\",\"considering\",\"unknown\"]},\"authority_signal\":{\"type\":\"string\",\"enum\":[\"decision_maker\",\"influencer\",\"unknown\"]},\"purchase_intent\":{\"type\":\"string\",\"enum\":[\"high\",\"medium\",\"low\",\"unknown\"]},\"timeline\":{\"type\":\"string\"},\"sentiment\":{\"type\":\"string\",\"enum\":[\"positive\",\"neutral\",\"negative\"]},\"risk_flags\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"maxItems\":12},\"recommended_next_action\":{\"type\":\"string\",\"enum\":[\"review\",\"discovery\",\"nurture\",\"reject\"]},\"confidence\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1},\"evidence\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"maxItems\":12}},\"required\":[\"intent\",\"needs\",\"pain_points\",\"buyer_role\",\"urgency\",\"budget_signal\",\"authority_signal\",\"purchase_intent\",\"timeline\",\"sentiment\",\"risk_flags\",\"recommended_next_action\",\"confidence\",\"evidence\"]},draftSchema={\"type\":\"object\",\"additionalProperties\":false,\"properties\":{\"subject\":{\"type\":\"string\",\"maxLength\":160},\"body\":{\"type\":\"string\",\"maxLength\":4000},\"cta\":{\"type\":\"string\"},\"claim_ids\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"maxItems\":12}},\"required\":[\"subject\",\"body\",\"cta\",\"claim_ids\"]},replySchema={\"type\":\"object\",\"additionalProperties\":false,\"properties\":{\"intent\":{\"type\":\"string\",\"enum\":[\"meeting\",\"question\",\"objection\",\"unsubscribe\",\"unknown\"]},\"confidence\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1},\"tool\":{\"type\":\"string\",\"enum\":[\"read_lead\",\"read_calendar\",\"crm_note\",\"crm_task\",\"external_send\",\"deal_stage\",\"discount\",\"cancellation\",\"none\"]}},\"required\":[\"intent\",\"confidence\",\"tool\"]};\nconst passed=[];function check(ok,label){if(!ok)throw Error(label);passed.push(label);}\ncheck(normalize({...sample,email:' CTO@EXAMPLE.COM '}).lead.email==='cto@example.com','canonical_email');check(normalize({...sample,consent:'true'}).lead.consent===false,'consent_not_coerced');check(normalize({...sample,email:'bad'}).errors.includes('INVALID_EMAIL'),'invalid_email');\nreturn [{json:{stage:\"normalize\",fixture_scope:'deterministic rules; DB/integrations verified by local system tests',passed,count:passed.length,external_side_effects:0}}];"},"position":[0,3200]}});
